const mongoose = require("mongoose");

const userSchema = new mongoose.Schema({
  firstName: {
    type: String,
    required: true
  },

  lastName: {
    type: String,
    required: true
  },

  mobile: {
    type: String,
    required: true
  },

  email: {
    type: String,
    required: true
  },

  address: {
    street: String,
    city: String,
    state: String,
    country: String
  },

  loginId: {
    type: String,
    required: true
  },

  password: {
    type: String,
    required: true
  },

  creationTime: {
    type: Date,
    default: Date.now
  },

  lastUpdatedOn: {
    type: Date,
    default: Date.now
  }
});

module.exports = mongoose.model("User", userSchema);